abstract class Shape { abstract int sides(); }
class Square extends Shape { int sides() { return 4; } }
public class Main { public static void main(String[] args) { System.out.println(new Square().sides()); } }

abstract class Greeting { void say() { System.out.println("Hello"); } abstract String language(); }
class English extends Greeting { String language() { return "English"; } }
public class Main { public static void main(String[] args) { English e = new English(); e.say(); System.out.println(e.language()); } }

abstract class Account { int id; Account(int id) { this.id = id; } abstract String type(); }
class Savings extends Account { Savings(int id) { super(id); } String type() { return "Savings"; } }
public class Main { public static void main(String[] args) { Savings s = new Savings(12); System.out.println(s.id + ":" + s.type()); } }

abstract class Device { abstract String category(); }
class Tablet extends Device { String category() { return "Tablet"; } }
public class Main { public static void main(String[] args) { Device d = new Tablet(); System.out.println(d.category()); } }

abstract class Report { void header() { System.out.println("Report"); } abstract int rows(); }
class SalesReport extends Report { int rows() { return 3; } }
public class Main { public static void main(String[] args) { SalesReport r = new SalesReport(); r.header(); System.out.println(r.rows()); } }
